"use client";

import ProductCard from "@/components/home/ProductCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useAuth } from "@/context/AuthContext";
import { useFavorites } from "@/context/FavoritesContext";
import {
  buildFullAddress,
  fetchProvinces,
  fetchWards,
  findProvince,
  findWard,
  type ProvinceOption,
  type WardOption,
} from "@/lib/locations";
import { formatVND, productImageUrl } from "@/lib/utils";
import {
  CheckCircle,
  ChevronDown,
  ChevronUp,
  Clock,
  Heart,
  Package,
  ReceiptText,
  Save,
  Star,
  UserCircle,
  X,
  XCircle,
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

type OrderStatus = "Tất cả" | "Đang xử lý" | "Đang giao" | "Đã giao" | "Đã hủy";

interface OrderItem {
  id: number;
  orderItemId?: number;
  name: string;
  image: string;
  price: number;
  quantity: number;
  review?: ApiReview | null;
}

interface Order {
  databaseId: number;
  id: string;
  rawStatus?: string;
  date: string;
  status: Exclude<OrderStatus, "Tất cả">;
  paymentStatus: string;
  address: string;
  paymentMethod: string;
  shipping: number;
  tax: number;
  discount: number;
  items: OrderItem[];
}

interface ApiOrderItem {
  id: number;
  product_id: number | null;
  product_name: string;
  product_image: string | null;
  price: number;
  quantity: number;
  review?: ApiReview | null;
}

interface ApiOrder {
  id: number;
  order_number: string;
  created_at: string;
  status: string;
  payment_status: string;
  payment_method: string;
  customer_address: string;
  recipient_address: string | null;
  shipping_fee: number;
  tax: number;
  discount: number;
  items: ApiOrderItem[];
}

interface ApiReview {
  id: number;
  rating: number;
  content?: string | null;
}

function getOrderSubtotal(order: Order) {
  return order.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

function getOrderTotal(order: Order) {
  return getOrderSubtotal(order) + order.shipping + order.tax - order.discount;
}

function getOrderItemCount(order: Order) {
  return order.items.reduce((sum, item) => sum + item.quantity, 0);
}

function mapOrderStatus(status: string): Exclude<OrderStatus, "Tất cả"> {
  if (status === "completed") return "Đã giao";
  if (status === "cancelled") return "Đã hủy";
  if (status === "shipping") return "Đang giao";

  return "Đang xử lý";
}

function mapPaymentMethod(paymentMethod: string) {
  if (paymentMethod === "cod") {
    return "Thanh toán khi nhận hàng";
  }

  if (paymentMethod === "momo") {
    return "Ví MoMo";
  }

  if (paymentMethod === "vnpay") {
    return "VNPay";
  }

  return paymentMethod;
}

function mapApiOrder(order: ApiOrder): Order {
  return {
    databaseId: order.id,
    id: order.order_number,
    rawStatus: order.status,
    date: new Intl.DateTimeFormat("vi-VN").format(new Date(order.created_at)),
    status: mapOrderStatus(order.status),
    paymentStatus: order.payment_status,
    address: order.recipient_address || order.customer_address,
    paymentMethod: mapPaymentMethod(order.payment_method),
    shipping: order.shipping_fee,
    tax: order.tax,
    discount: order.discount,
    items: order.items.map((item) => ({
      id: item.product_id ?? item.id,
      orderItemId: item.id,
      name: item.product_name,
      image: item.product_image || "/images/NoImage.jpg",
      price: item.price,
      quantity: item.quantity,
      review: item.review || null,
    })),
  };
}

export default function ProfilePage() {
  const { user, token, updateUser } = useAuth();
  const { favorites } = useFavorites();
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<"info" | "orders" | "favorites">("info");
  const [orderFilter, setOrderFilter] = useState<OrderStatus>("Tất cả");
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);
  const [isMounted, setIsMounted] = useState(false);
  const [infoForm, setInfoForm] = useState({ phone: "", address: "", province_code: "", ward_code: "" });
  const [saveMessage, setSaveMessage] = useState("");
  const [saveError, setSaveError] = useState("");
  const [provinces, setProvinces] = useState<ProvinceOption[]>([]);
  const [wards, setWards] = useState<WardOption[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [isOrdersLoading, setIsOrdersLoading] = useState(false);
  const [ordersError, setOrdersError] = useState("");
  const [cancellingOrderId, setCancellingOrderId] = useState<number | null>(null);
  const [reviewTarget, setReviewTarget] = useState<{ orderId: string; item: OrderItem } | null>(null);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewContent, setReviewContent] = useState("");
  const [reviewError, setReviewError] = useState("");
  const [isSubmittingReview, setIsSubmittingReview] = useState(false);

  const filteredOrders = useMemo(
    () =>
      orders.filter(
        (order) => orderFilter === "Tất cả" || order.status === orderFilter
      ),
    [orderFilter, orders]
  );

  useEffect(() => {
    if (user) {
      setInfoForm({
        phone: user.phone || "",
        address: user.address_detail || user.address || "",
        province_code: user.province_code || "",
        ward_code: user.ward_code || "",
      });
    }
  }, [user]);

  useEffect(() => {
    fetchProvinces()
      .then(setProvinces)
      .catch(() => setSaveError("Không thể tải danh sách tỉnh/thành."));
  }, []);

  useEffect(() => {
    if (!infoForm.province_code) {
      setWards([]);
      return;
    }

    fetchWards(infoForm.province_code)
      .then((loadedWards) => {
        setWards(loadedWards);
        setInfoForm((current) =>
          current.ward_code && !loadedWards.some((ward) => ward.code === current.ward_code)
            ? { ...current, ward_code: "" }
            : current
        );
      })
      .catch(() => setSaveError("Không thể tải danh sách phường/xã."));
  }, [infoForm.province_code]);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (isMounted && !user) {
      router.push("/login");
    }
  }, [user, router, isMounted]);

  useEffect(() => {
    if (!token) {
      return;
    }

    const controller = new AbortController();

    async function fetchOrders() {
      setIsOrdersLoading(true);
      setOrdersError("");

      try {
        const response = await fetch("/api/orders", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
          signal: controller.signal,
        });

        const data = await response.json();

        if (!response.ok) {
          setOrdersError(data.message || "Không tải được đơn hàng.");
          return;
        }

        setOrders(data.map(mapApiOrder));
      } catch {
        if (!controller.signal.aborted) {
          setOrdersError("Không kết nối được tới máy chủ.");
        }
      } finally {
        if (!controller.signal.aborted) {
          setIsOrdersLoading(false);
        }
      }
    }

    fetchOrders();

    return () => controller.abort();
  }, [token]);

  const handleSaveInfo = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaveError("");
    setSaveMessage("");

    if (!token) {
      setSaveError("Phiên đăng nhập đã hết hạn.");
      return;
    }

    const province = findProvince(provinces, infoForm.province_code);
    const ward = findWard(wards, infoForm.ward_code);

    if (!province || !ward) {
      setSaveError("Vui lòng chọn đầy đủ tỉnh/thành và phường/xã.");
      return;
    }

    try {
      const response = await fetch("/api/user", {
        method: "PATCH",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          phone: infoForm.phone,
          address: buildFullAddress(infoForm.address, ward, province),
          address_detail: infoForm.address,
          province_code: province.code,
          ward_code: ward.code,
        }),
      });
      const data = await response.json();

      if (!response.ok) {
        setSaveError(data.message || "Không thể cập nhật thông tin.");
        return;
      }

      updateUser(data.user);
      setSaveMessage("Cập nhật thông tin thành công.");
      window.setTimeout(() => setSaveMessage(""), 2500);
    } catch {
      setSaveError("Không kết nối được tới máy chủ.");
    }
  };

  const toggleOrderDetail = (orderId: string) => {
    setExpandedOrderId((current) => (current === orderId ? null : orderId));
  };

  const canCancelOrder = (order: Order) =>
    ["pending", "processing"].includes(order.rawStatus || "") && order.paymentStatus !== "paid";

  const handleCancelOrder = async (order: Order) => {
    if (!token || !canCancelOrder(order)) return;

    const confirmed = window.confirm(`Bạn có chắc muốn hủy đơn ${order.id}?`);
    if (!confirmed) return;

    setCancellingOrderId(order.databaseId);
    setOrdersError("");

    try {
      const response = await fetch(`/api/orders/${order.databaseId}/cancel`, {
        method: "PATCH",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${token}`,
        },
      });
      const data = await response.json();

      if (!response.ok) {
        setOrdersError(data.message || "Không thể hủy đơn hàng.");
        return;
      }

      const cancelledOrder = mapApiOrder(data);
      setOrders((currentOrders) =>
        currentOrders.map((currentOrder) =>
          currentOrder.databaseId === cancelledOrder.databaseId ? cancelledOrder : currentOrder
        )
      );
    } catch {
      setOrdersError("Không kết nối được tới máy chủ.");
    } finally {
      setCancellingOrderId(null);
    }
  };

  const openReviewModal = (orderId: string, item: OrderItem) => {
    setReviewTarget({ orderId, item });
    setReviewRating(item.review?.rating || 5);
    setReviewContent(item.review?.content || "");
    setReviewError("");
  };

  const closeReviewModal = () => {
    setReviewTarget(null);
    setReviewRating(5);
    setReviewContent("");
    setReviewError("");
  };

  const handleSubmitReview = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!token || !reviewTarget?.item.orderItemId) return;

    setIsSubmittingReview(true);
    setReviewError("");

    try {
      const response = await fetch("/api/reviews", {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          product_id: reviewTarget.item.id,
          order_item_id: reviewTarget.item.orderItemId,
          rating: reviewRating,
          content: reviewContent.trim() || null,
        }),
      });
      const data = await response.json();

      if (!response.ok) {
        setReviewError(data.message || "Không thể gửi đánh giá.");
        return;
      }

      setOrders((currentOrders) =>
        currentOrders.map((order) =>
          order.id === reviewTarget.orderId
            ? {
                ...order,
                items: order.items.map((item) =>
                  item.orderItemId === reviewTarget.item.orderItemId
                    ? {
                        ...item,
                        review: {
                          id: data.id,
                          rating: data.rating,
                          content: data.content,
                        },
                      }
                    : item
                ),
              }
            : order
        )
      );
      closeReviewModal();
    } catch {
      setReviewError("Không kết nối được tới máy chủ.");
    } finally {
      setIsSubmittingReview(false);
    }
  };

  if (!isMounted || !user) return null;

  return (
    <div className="container mx-auto px-4 py-12 min-h-[calc(100vh-160px)]">
      <div className="flex flex-col md:flex-row gap-8">
        <div className="w-full md:w-1/4">
          <div className="bg-card rounded-2xl border border-border p-6 shadow-sm sticky top-24">
            <div className="flex flex-col items-center text-center pb-6 border-b border-border">
              {user.avatar ? (
                <img
                  src={user.avatar}
                  alt="Avatar"
                  className="w-24 h-24 rounded-full bg-accent mb-4 shadow-md"
                />
              ) : (
                <div className="w-24 h-24 rounded-full bg-primary/20 flex items-center justify-center mb-4">
                  <span className="text-3xl font-bold text-primary">
                    {user.name.charAt(0)}
                  </span>
                </div>
              )}
              <h2 className="text-xl font-bold text-foreground">{user.name}</h2>
              <p className="text-sm text-muted-foreground">{user.email}</p>
            </div>

            <div className="flex flex-col gap-2 mt-6">
              <button
                onClick={() => setActiveTab("info")}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${
                  activeTab === "info"
                    ? "bg-primary text-primary-foreground shadow-md"
                    : "text-muted-foreground hover:bg-accent hover:text-foreground"
                }`}
              >
                <UserCircle className="w-5 h-5" />
                Thông tin cá nhân
              </button>
              <button
                onClick={() => setActiveTab("orders")}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${
                  activeTab === "orders"
                    ? "bg-primary text-primary-foreground shadow-md"
                    : "text-muted-foreground hover:bg-accent hover:text-foreground"
                }`}
              >
                <Package className="w-5 h-5" />
                Đơn hàng của tôi
              </button>
              <button
                onClick={() => setActiveTab("favorites")}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${
                  activeTab === "favorites"
                    ? "bg-primary text-primary-foreground shadow-md"
                    : "text-muted-foreground hover:bg-accent hover:text-foreground"
                }`}
              >
                <Heart className="w-5 h-5" />
                Sản phẩm yêu thích
              </button>
            </div>
          </div>
        </div>

        <div className="w-full md:w-3/4">
          <div className="bg-card rounded-2xl border border-border p-6 shadow-sm min-h-[500px]">
            {activeTab === "info" && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                <h3 className="text-2xl font-bold text-foreground mb-6">
                  Thông tin cá nhân
                </h3>
                <form onSubmit={handleSaveInfo} className="space-y-4 max-w-lg">
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground">
                      Họ và tên
                    </label>
                    <Input disabled value={user.name} className="bg-muted" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground">
                      Email
                    </label>
                    <Input disabled value={user.email} className="bg-muted" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground">
                      Số điện thoại
                    </label>
                    <Input
                      placeholder="Nhập số điện thoại"
                      value={infoForm.phone}
                      onChange={(e) =>
                        setInfoForm({ ...infoForm, phone: e.target.value })
                      }
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground">
                      Địa chỉ giao hàng
                    </label>
                    <Input
                      placeholder="Số nhà, đường, phường/xã..."
                      value={infoForm.address}
                      onChange={(e) =>
                        setInfoForm({ ...infoForm, address: e.target.value })
                      }
                    />
                  </div>
                  <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                    <div className="space-y-2">
                      <label className="text-sm font-medium text-foreground">
                        Tỉnh/Thành phố
                      </label>
                      <Select
                        value={infoForm.province_code}
                        onValueChange={(value) =>
                          setInfoForm({ ...infoForm, province_code: value, ward_code: "" })
                        }
                      >
                        <SelectTrigger className="h-11 rounded-lg">
                          <SelectValue placeholder="Chọn tỉnh/thành" />
                        </SelectTrigger>
                        <SelectContent>
                          {provinces.map((province) => (
                            <SelectItem key={province.code} value={province.code}>
                              {province.full_name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-medium text-foreground">
                        Phường/Xã
                      </label>
                      <Select
                        value={infoForm.ward_code}
                        onValueChange={(value) => setInfoForm({ ...infoForm, ward_code: value })}
                        disabled={!infoForm.province_code}
                      >
                        <SelectTrigger className="h-11 rounded-lg">
                          <SelectValue placeholder={infoForm.province_code ? "Chọn phường/xã" : "Chọn tỉnh trước"} />
                        </SelectTrigger>
                        <SelectContent>
                          {wards.map((ward) => (
                            <SelectItem key={ward.code} value={ward.code}>
                              {ward.full_name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                  <Button type="submit" className="mt-4">
                    <Save className="w-4 h-4 mr-2" /> Lưu thay đổi
                  </Button>
                  {saveError && (
                    <p className="text-sm font-medium text-red-600">
                      {saveError}
                    </p>
                  )}
                  {saveMessage && (
                    <p className="text-sm font-medium text-green-600">
                      {saveMessage}
                    </p>
                  )}
                </form>
              </div>
            )}

            {activeTab === "orders" && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-6 gap-4">
                  <div>
                    <h3 className="text-2xl font-bold text-foreground">
                      Đơn hàng của tôi
                    </h3>
                    <p className="text-sm text-muted-foreground mt-1">
                      Theo dõi trạng thái và xem chi tiết từng món trong đơn hàng.
                    </p>
                  </div>
                  <div className="flex bg-muted p-1 rounded-xl w-fit">
                    {(["Tất cả", "Đang xử lý", "Đang giao", "Đã giao", "Đã hủy"] as OrderStatus[]).map(
                      (status) => (
                        <button
                          key={status}
                          onClick={() => {
                            setOrderFilter(status);
                            setExpandedOrderId(null);
                          }}
                          className={`px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${
                            orderFilter === status
                              ? "bg-background text-foreground shadow-sm"
                              : "text-muted-foreground hover:text-foreground"
                          }`}
                        >
                          {status}
                        </button>
                      )
                    )}
                  </div>
                </div>

                {ordersError && (
                  <p className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
                    {ordersError}
                  </p>
                )}

                {isOrdersLoading ? (
                  <div className="text-center py-12 bg-muted/30 rounded-2xl border border-dashed border-border">
                    <Package className="w-12 h-12 text-muted-foreground/50 mx-auto mb-3 animate-pulse" />
                    <p className="text-muted-foreground">Đang tải đơn hàng...</p>
                  </div>
                ) : filteredOrders.length === 0 ? (
                  <div className="text-center py-12 bg-muted/30 rounded-2xl border border-dashed border-border">
                    <Package className="w-12 h-12 text-muted-foreground/50 mx-auto mb-3" />
                    <p className="text-muted-foreground">Không có đơn hàng nào.</p>
                  </div>
                ) : (
                  <div className="flex flex-col gap-4">
                    {filteredOrders.map((order) => {
                      const isExpanded = expandedOrderId === order.id;
                      const subtotal = getOrderSubtotal(order);
                      const total = getOrderTotal(order);
                      const itemCount = getOrderItemCount(order);
                      const isCancellable = canCancelOrder(order);
                      const isCancelling = cancellingOrderId === order.databaseId;
                      const statusClass =
                        order.status === "Đã hủy"
                          ? "bg-rose-100 text-rose-700 border border-rose-200 hover:bg-rose-200/80"
                          : order.status === "Đã giao"
                            ? "bg-green-100 text-green-700 border border-green-200 hover:bg-green-200/80"
                            : order.status === "Đang giao"
                              ? "bg-sky-100 text-sky-700 border border-sky-200 hover:bg-sky-200/80"
                              : "bg-orange-100 text-orange-700 border border-orange-200 hover:bg-orange-200/80";

                      return (
                        <div
                          key={order.id}
                          className="border border-border rounded-xl p-5 hover:shadow-md transition-shadow"
                        >
                          <div className="flex flex-col gap-4 border-b border-border/50 pb-4 sm:flex-row sm:items-start sm:justify-between">
                            <div>
                              <p className="font-semibold text-lg text-foreground">
                                Mã đơn: {order.id}
                              </p>
                              <p className="text-sm text-muted-foreground mt-1">
                                Ngày đặt: {order.date} • {itemCount} sản phẩm
                              </p>
                              <p className="text-sm text-muted-foreground mt-1">
                                Thanh toán: {order.paymentMethod}
                              </p>
                            </div>

                            <div className="flex flex-col items-start gap-2 sm:items-end sm:justify-end">
                              <button
                                type="button"
                                onClick={() => toggleOrderDetail(order.id)}
                                aria-expanded={isExpanded}
                                aria-label={
                                  isExpanded
                                    ? `Ẩn chi tiết đơn ${order.id}`
                                    : `Xem chi tiết đơn ${order.id}`
                                }
                                className={`px-3 py-1.5 rounded-full flex items-center gap-2 w-fit transition-all hover:shadow-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30 ${statusClass}`}
                              >
                                {order.status === "Đã hủy" ? (
                                  <XCircle className="w-4 h-4" />
                                ) : order.status === "Đã giao" ? (
                                  <CheckCircle className="w-4 h-4" />
                                ) : (
                                  <Clock className="w-4 h-4" />
                                )}
                                <span className="text-sm font-medium">
                                  {order.status}
                                </span>
                                <span className="ml-1 flex h-6 w-6 items-center justify-center rounded-full bg-background/70">
                                  {isExpanded ? (
                                    <ChevronUp className="w-4 h-4" />
                                  ) : (
                                    <ChevronDown className="w-4 h-4" />
                                  )}
                                </span>
                              </button>
                              {isCancellable && (
                                <button
                                  type="button"
                                  onClick={() => handleCancelOrder(order)}
                                  disabled={isCancelling}
                                  className="inline-flex h-9 items-center gap-2 rounded-lg border border-rose-200 px-3 text-sm font-semibold text-rose-600 transition hover:bg-rose-50 disabled:cursor-not-allowed disabled:opacity-60"
                                >
                                  <XCircle className="h-4 w-4" />
                                  {isCancelling ? "Đang hủy..." : "Hủy đơn"}
                                </button>
                              )}
                            </div>
                          </div>

                          <div className="flex justify-between items-center pt-4">
                            <span className="text-muted-foreground">Tổng tiền:</span>
                            <span className="text-xl font-bold text-primary">
                              {formatVND(total)}
                            </span>
                          </div>

                          {isExpanded && (
                            <div className="mt-5 rounded-xl border border-border bg-muted/20 p-4 animate-in fade-in slide-in-from-top-2 duration-200">
                              <div className="flex items-center gap-2 mb-4">
                                <ReceiptText className="w-5 h-5 text-primary" />
                                <h4 className="font-semibold text-foreground">
                                  Chi tiết đơn hàng
                                </h4>
                              </div>

                              <div className="space-y-3">
                                {order.items.map((item) => (
                                  <div
                                    key={item.id}
                                    className="flex flex-col gap-3 rounded-lg border border-border bg-background p-3 sm:flex-row sm:items-center"
                                  >
                                    <img
                                      src={productImageUrl(item.image)}
                                      alt={item.name}
                                      className="h-20 w-20 rounded-md object-cover bg-muted"
                                    />
                                    <div className="min-w-0 flex-1">
                                      <p className="font-medium text-foreground">
                                        {item.name}
                                      </p>
                                      <p className="text-sm text-muted-foreground mt-1">
                                        Số lượng: {item.quantity} • Đơn giá:{" "}
                                        {formatVND(item.price)}
                                      </p>
                                      <Link
                                        href={`/product/${item.id}`}
                                        className="text-sm font-medium text-primary hover:underline mt-1 inline-block"
                                      >
                                        Xem sản phẩm
                                      </Link>
                                      {order.rawStatus === "completed" && (
                                        <button
                                          type="button"
                                          onClick={() => openReviewModal(order.id, item)}
                                          className="ml-0 mt-2 inline-flex h-9 items-center gap-2 rounded-lg border border-primary/20 px-3 text-sm font-semibold text-primary transition hover:bg-primary/10 sm:ml-3 sm:mt-0"
                                        >
                                          <Star className="h-4 w-4" />
                                          {item.review ? "Sửa đánh giá" : "Đánh giá"}
                                        </button>
                                      )}
                                    </div>
                                    <div className="text-left sm:text-right">
                                      <p className="text-sm text-muted-foreground">
                                        Thành tiền
                                      </p>
                                      <p className="font-semibold text-foreground">
                                        {formatVND(item.price * item.quantity)}
                                      </p>
                                    </div>
                                  </div>
                                ))}
                              </div>

                              <div className="mt-4 grid gap-4 lg:grid-cols-[1fr_320px]">
                                <div className="rounded-lg border border-border bg-background p-4">
                                  <p className="text-sm font-semibold text-foreground">
                                    Địa chỉ giao hàng
                                  </p>
                                  <p className="text-sm text-muted-foreground mt-1">
                                    {order.address}
                                  </p>
                                </div>

                                <div className="rounded-lg border border-border bg-background p-4 space-y-2">
                                  <div className="flex justify-between text-sm">
                                    <span className="text-muted-foreground">
                                      Tạm tính
                                    </span>
                                    <span className="font-medium">
                                      {formatVND(subtotal)}
                                    </span>
                                  </div>
                                  <div className="flex justify-between text-sm">
                                    <span className="text-muted-foreground">
                                      Phí vận chuyển
                                    </span>
                                    <span className="font-medium">
                                      {order.shipping === 0
                                        ? "Miễn phí"
                                        : formatVND(order.shipping)}
                                    </span>
                                  </div>
                                  <div className="flex justify-between text-sm">
                                    <span className="text-muted-foreground">
                                      Ưu đãi
                                    </span>
                                    <span className="font-medium text-green-600">
                                      -{formatVND(order.discount)}
                                    </span>
                                  </div>
                                  <div className="flex justify-between text-sm">
                                    <span className="text-muted-foreground">
                                      Thuế
                                    </span>
                                    <span className="font-medium">
                                      {formatVND(order.tax)}
                                    </span>
                                  </div>
                                  <div className="flex justify-between border-t border-border pt-2">
                                    <span className="font-semibold text-foreground">
                                      Tổng cộng
                                    </span>
                                    <span className="font-bold text-primary">
                                      {formatVND(total)}
                                    </span>
                                  </div>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            {activeTab === "favorites" && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                <h3 className="text-2xl font-bold text-foreground mb-6">
                  Sản phẩm yêu thích
                </h3>
                {favorites.length === 0 ? (
                  <div className="text-center py-12 bg-muted/30 rounded-2xl border border-dashed border-border">
                    <Heart className="w-12 h-12 text-muted-foreground/50 mx-auto mb-3" />
                    <p className="text-muted-foreground">
                      Bạn chưa có sản phẩm yêu thích nào.
                    </p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    {favorites.map((product) => (
                      <ProductCard key={product.id} product={product} />
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
      {reviewTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-lg rounded-2xl border border-border bg-card shadow-xl">
            <div className="flex items-start justify-between gap-4 border-b border-border px-5 py-4">
              <div>
                <h3 className="text-xl font-bold text-foreground">Đánh giá sản phẩm</h3>
                <p className="mt-1 text-sm text-muted-foreground">{reviewTarget.item.name}</p>
              </div>
              <button
                type="button"
                onClick={closeReviewModal}
                className="flex h-9 w-9 items-center justify-center rounded-lg border border-border text-muted-foreground transition hover:bg-muted hover:text-foreground"
                aria-label="Đóng đánh giá"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <form onSubmit={handleSubmitReview} className="space-y-4 p-5">
              <div className="flex items-center gap-2">
                {[1, 2, 3, 4, 5].map((rating) => (
                  <button
                    key={rating}
                    type="button"
                    onClick={() => setReviewRating(rating)}
                    className="rounded-lg p-1 transition hover:bg-primary/10"
                    aria-label={`Chọn ${rating} sao`}
                  >
                    <Star
                      className={`h-7 w-7 ${
                        rating <= reviewRating ? "fill-primary text-primary" : "text-muted-foreground/40"
                      }`}
                    />
                  </button>
                ))}
              </div>

              <label className="block text-sm font-medium text-foreground">
                Nội dung đánh giá
                <textarea
                  value={reviewContent}
                  onChange={(event) => setReviewContent(event.target.value)}
                  className="mt-2 min-h-28 w-full rounded-xl border border-border bg-background px-3 py-2 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/20"
                  placeholder="Chia sẻ trải nghiệm của bạn về sản phẩm..."
                />
              </label>

              {reviewError && (
                <p className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm font-medium text-red-700">
                  {reviewError}
                </p>
              )}

              <div className="flex flex-wrap justify-end gap-2">
                <button
                  type="button"
                  onClick={closeReviewModal}
                  className="h-10 rounded-lg border border-border px-4 text-sm font-semibold text-foreground transition hover:bg-muted"
                >
                  Hủy
                </button>
                <button
                  type="submit"
                  disabled={isSubmittingReview}
                  className="h-10 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground transition hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {isSubmittingReview ? "Đang gửi..." : "Gửi đánh giá"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
